#!/usr/bin/env node

import { createInterface } from 'node:readline/promises'
import { stdin as input, stdout as output } from 'node:process'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
  chmodSync,
  copyFileSync,
} from 'node:fs'
import { homedir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { gunzipSync } from 'node:zlib'

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url))
const AGENTIC_ROOT = resolve(SCRIPT_DIR, '..')
const ARCHIVE = ''

const SKIP_SKILLS = new Set([
  'caveman',
  'explain',
  'plan',
  'generate-unit-test',
  'generate-mermaid',
])
const SKIP_RULES = new Set(['skill-caveman.mdc'])

function filesFromArchive() {
  const json = gunzipSync(Buffer.from(ARCHIVE, 'base64')).toString('utf8')
  return JSON.parse(json)
}

function log(msg) {
  output.write(`  ${msg}\n`)
}

function warn(msg) {
  output.write(`  [!] ${msg}\n`)
}

function die(msg) {
  warn(msg)
  process.exit(1)
}

function expandPath(raw) {
  let p = String(raw ?? '').trim().replace(/^['"]|['"]$/g, '')
  if (!p) return p
  if (p.startsWith('~')) {
    p = join(homedir(), p.slice(1).replace(/^[\\/]+/, ''))
  }
  return resolve(p)
}

function loadAgenticConfig() {
  const path = join(AGENTIC_ROOT, 'store', 'agentic.config.json')
  if (!existsSync(path)) return {}
  try {
    return JSON.parse(readFileSync(path, 'utf8'))
  } catch {
    return {}
  }
}

function guessPdRoot(config) {
  const env = process.env.PD_ROOT || process.env.AGENTIC_PD_ROOT
  if (env) return expandPath(env)
  const codeRoot = process.env.AGENTIC_CODE_ROOT || config.codeRoot
  const candidates = [
    codeRoot ? join(expandPath(codeRoot), 'pd') : null,
    join(homedir(), 'code', 'pd'),
    join(homedir(), 'projects', 'pd'),
    join(homedir(), 'Projects', 'pd'),
    resolve(AGENTIC_ROOT, '..', 'pd'),
  ].filter(Boolean)
  return candidates.find((p) => existsSync(p)) ?? candidates[0]
}

function guessBrainRoot(config) {
  const env = process.env.PD_BRAIN || process.env.AGENTIC_BRAIN_DIR
  if (env) return expandPath(env)
  if (config.brainRoot) return expandPath(config.brainRoot)
  return join(homedir(), 'SecondBrain', 'Second Brain')
}

function parseArgs(argv) {
  const out = { yes: false, agent: null, pd: null, brain: null }
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]
    if (a === '--yes' || a === '-y') out.yes = true
    else if (a === '--agent' || a === '--for') out.agent = argv[++i]
    else if (a === '--pd') out.pd = argv[++i]
    else if (a === '--brain') out.brain = argv[++i]
    else if (a.startsWith('--agent=')) out.agent = a.slice('--agent='.length)
    else if (a.startsWith('--pd=')) out.pd = a.slice('--pd='.length)
    else if (a.startsWith('--brain=')) out.brain = a.slice('--brain='.length)
  }
  if (process.env.PD_AGENT) out.agent = process.env.PD_AGENT
  return out
}

function normalizeAgent(raw) {
  const v = String(raw ?? '')
    .trim()
    .toLowerCase()
  if (['cursor', 'c', '1'].includes(v)) return 'cursor'
  if (['claude', 'claude-code', 'anthropic', 'a', '2'].includes(v)) return 'claude'
  return null
}

function looksLikePd(pdRoot) {
  return (
    existsSync(join(pdRoot, 'apps', 'book_service')) ||
    existsSync(join(pdRoot, 'helm')) ||
    existsSync(join(pdRoot, 'infrastructure', 'scripts', 'install_k8s_local.sh'))
  )
}

function parseGlobs(fm) {
  const block = fm.match(/^globs:\s*\n((?:\s+-\s+.+\n?)+)/m)
  if (block) {
    return [...block[1].matchAll(/-\s+["']?([^"'\n]+)["']?/g)].map((m) => m[1].trim())
  }
  const inline = fm.match(/^globs:\s*\[([^\]]*)\]/m)
  if (!inline) return []
  return inline[1]
    .split(',')
    .map((s) => s.trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean)
}

function convertRuleForClaude(content) {
  const m = content.match(/^---\n([\s\S]*?)\n---\n?/)
  if (!m) return content
  const fm = m[1]
  const body = content.slice(m[0].length)
  const desc = (fm.match(/^description:\s*(.+)$/m) || [, ''])[1].trim()
  const globs = parseGlobs(fm)
  const lines = ['---']
  if (desc) lines.push(`description: ${desc}`)
  if (globs.length) {
    lines.push('paths:')
    for (const g of globs) lines.push(`  - ${JSON.stringify(g)}`)
  }
  lines.push('---', '')
  return `${lines.join('\n')}${body}`
}

function rewritePaths(text, agent, pdRoot, brainRoot) {
  let out = text
    .split('/Users/perluszdavid/code/pd')
    .join(pdRoot)
    .split('/Users/perluszdavid/SecondBrain/Second Brain')
    .join(brainRoot)
  if (agent === 'claude') {
    out = out
      .split('.cursor/skills/')
      .join('.claude/skills/')
      .split('.cursor/rules/')
      .join('.claude/rules/')
      .split('~/.cursor/skills/')
      .join('~/.claude/skills/')
      .split('.mdc')
      .join('.md')
  }
  return out
}

function agentsMarkdown(agent, pdRoot, brainRoot) {
  const rulesDir = agent === 'claude' ? '.claude/rules' : '.cursor/rules'
  const skillsDir = agent === 'claude' ? '.claude/skills' : '.cursor/skills'
  const k8s = agent === 'claude' ? `${rulesDir}/skill-k8s-local-dev.md` : `${rulesDir}/skill-k8s-local-dev.mdc`
  const svc = agent === 'claude' ? `${rulesDir}/skill-service-layer-tests.md` : `${rulesDir}/skill-service-layer-tests.mdc`
  const rootFile = agent === 'claude' ? 'CLAUDE.md' : 'AGENTS.md'
  return `# pd — Agent context

Publishing platform monorepo. Primary work: Jira tickets and prompted implementation tasks.

## Orientation (code)

Graph: \`graphify-out/graph.json\`. See \`${rulesDir}/graphify.md${agent === 'cursor' ? 'c' : ''}\` for **when** to use graphify vs grep.

- **Structural / cross-service** → \`graphify query\` or \`graphify path\` with **symbol seeds** (class, service, method names)
- **Literal in log / config / ticket ID** → Grep/Glob first, then Read
- After PHP/code edits: \`graphify update .\` (use \`--force\` if overwrite refused)

Wiki nav: \`graphify-out/wiki/index.md\` (prefer over \`GRAPH_REPORT.md\` for browsing).

## Orientation (knowledge)

Durable notes and patterns live in the **Second Brain** vault, not in this repo:

- Vault: \`${brainRoot}\`
- pd dev wiki: \`wiki/projects/pd/\` (overview, gotchas, ticket checklist)
- pd concepts: \`wiki/concepts/\` (e.g. [[book-manager]])
- Code-graph mirror (read-only, Agentic OS): \`projects/pd/\`

Read vault \`index.md\` before answering "what do we know about pd …" questions.

## Task workflow

Follow the global \`task-loop\` skill for every implementation (Jira **or** a plain prompt). \`ticket-loop\` is an alias. Do **not** keep a pd fork of that loop under \`${skillsDir}/\`.

| Step | Skill / rule |
|------|----------------|
| 0 Branch (Jira URL/key only) | \`jira-branch-workflow\` — hotfix from \`master\`, feature from \`develop\`. Skip if no Jira. |
| 1 Intent | Success criteria from ticket or prompt. Non-trivial: \`unlazy\` gates before Act |
| 1.5 Grill | \`grill-with-docs\` when domain language is fuzzy |
| 2 Triage | Literal → grep; structure → graphify with symbol seeds; domain → brain wiki |
| 3 Act | Ponytail ladder — smallest diff, DTOs. Bugs with a cheap service-layer Pest/pytest target: failing test in the k3d pod **before** the production change; otherwise say why and Act |
| 4 Verify | **Pest** (PHP) or **pytest** (Python) in k3d pod when non-trivial — \`${k8s}\`. **Service layer only** — \`${svc}\`. **Trivial one-liners need no test.** |
| 5 Repair | Re-triage and re-test on failure |
| 6 Review | \`review-checklist\` on full branch diff — mandatory before close when code changed |
| 7 Compound | \`compound-fix\` → \`gotchas.md\` if reusable; \`graphify update .\` |

Do not skip step 6 (review) when code changed. Do not run Pest/pytest on the host. Trivial one-liners need no test (ponytail).

Repo path: \`${pdRoot}\`
Agent instructions: \`${rootFile}\`

## High-signal areas (bootstrap hint)

- \`BookManagerService\` — \`apps/book_service/src/Domain/Service/BookManagerService.php\`
- Validation rules — \`apps/book_service/src/Domain/Rules/BookManagerRules.yaml\`
- DTOs — \`apps/book_service/src/Domain/DTO/\`

## What not to do

- Do not dump every Jira ticket into the brain — file **patterns**, not diffs.
- Do not hand-edit \`graphify-out/\` or vault \`projects/pd/\` (mirrors).
- Do not run graphify with ticket IDs or vague symptoms — seeds must be code symbols.
- Do not grep the whole repo when \`graphify path\` between two known services would be shorter.
- Do not end a code-change session without a branch review; run Pest/pytest in k8s when the change is non-trivial (trivial one-liners need no test).
`
}

function ensureDir(dir) {
  mkdirSync(dir, { recursive: true })
}

function writeText(path, content) {
  ensureDir(dirname(path))
  writeFileSync(path, content)
}

function backupIfExists(path) {
  if (!existsSync(path)) return
  const bak = `${path}.pd-install.bak`
  if (!existsSync(bak)) copyFileSync(path, bak)
}

function installOverlay(files, agent, pdRoot, brainRoot) {
  const skillsRoot = join(pdRoot, agent === 'claude' ? '.claude' : '.cursor', 'skills')
  const rulesRoot = join(pdRoot, agent === 'claude' ? '.claude' : '.cursor', 'rules')
  let skills = 0
  let rules = 0

  for (const [rel, raw] of Object.entries(files)) {
    const content = rewritePaths(raw, agent, pdRoot, brainRoot)
    if (rel.startsWith('skills/')) {
      const rest = rel.slice('skills/'.length)
      const name = rest.split('/')[0]
      if (SKIP_SKILLS.has(name)) continue
      writeText(join(skillsRoot, rest), content)
      skills++
      continue
    }
    if (rel.startsWith('rules/')) {
      const name = rel.slice('rules/'.length)
      if (SKIP_RULES.has(name)) continue
      const body = agent === 'claude' ? convertRuleForClaude(content) : content
      const destName =
        agent === 'claude' ? name.replace(/\.mdc$/i, '.md') : name
      writeText(join(rulesRoot, destName), body)
      rules++
    }
  }

  if (agent === 'cursor') {
    const hook = files['hooks/helm-dependency-before-upgrade.sh']
    if (hook) {
      const hookPath = join(pdRoot, '.cursor', 'hooks', 'helm-dependency-before-upgrade.sh')
      writeText(hookPath, hook)
      try {
        chmodSync(hookPath, 0o755)
      } catch {
      }
    }
    if (files['hooks.json']) {
      writeText(join(pdRoot, '.cursor', 'hooks.json'), files['hooks.json'])
    }
  }

  const md = agentsMarkdown(agent, pdRoot, brainRoot)
  if (agent === 'claude') {
    backupIfExists(join(pdRoot, 'CLAUDE.md'))
    writeText(join(pdRoot, 'CLAUDE.md'), md)
    writeText(join(pdRoot, '.claude', 'CLAUDE.md'), md)
    backupIfExists(join(pdRoot, 'AGENTS.md'))
    writeText(join(pdRoot, 'AGENTS.md'), md)
  } else {
    backupIfExists(join(pdRoot, 'AGENTS.md'))
    writeText(join(pdRoot, 'AGENTS.md'), md)
  }

  return { skills, rules }
}

function today() {
  return new Date().toISOString().slice(0, 10)
}

function ensureIndex(brainRoot) {
  const indexPath = join(brainRoot, 'index.md')
  const links = [
    '- [[pd/overview]] - pd monorepo, stack, Jira workflow',
    '- [[pd/glossary]] - pd domain language',
    '- [[pd/distribution-api]] - public `/v2/distribution` book API; withdraw a book via unpublish',
    '- [[pd/gotchas]] - reusable pd lessons from tickets',
    '- [[pd/conventions]] - PHP class/layer naming (Service, Repository, DTO)',
    '- [[pd/subsystems]] - entry symbols for graphify triage',
    '- [[pd/ticket-checklist]] - per-ticket graphify + compound workflow',
    '- [[book-manager]] - BookManager domain in pd (validation, DTOs, rules YAML, withdraw vs delete)',
  ]
  if (!existsSync(indexPath)) {
    writeText(
      indexPath,
      `---
type: index
updated: ${today()}
---

# Index

## Projects (dev wiki — hand-edited)

${links.join('\n')}
`,
    )
    return
  }
  let content = readFileSync(indexPath, 'utf8')
  const missing = links.filter((line) => {
    const key = line.match(/\[\[([^\]]+)\]\]/)[1]
    return !content.includes(`[[${key}]]`) && !content.includes(`[[${key}|`)
  })
  if (missing.length === 0) return
  const marker = '## Projects (dev wiki'
  const idx = content.indexOf(marker)
  if (idx === -1) {
    content = `${content.trimEnd()}\n\n## Projects (dev wiki — hand-edited)\n\n${missing.join('\n')}\n`
  } else {
    const next = content.indexOf('\n## ', idx + marker.length)
    const insertAt = next === -1 ? content.length : next
    content = `${content.slice(0, insertAt).trimEnd()}\n${missing.join('\n')}\n${content.slice(insertAt)}`
  }
  writeFileSync(indexPath, content)
}

function appendLog(brainRoot) {
  const logPath = join(brainRoot, 'log.md')
  const line = `## [${today()}] ingest | pd overlay install\n`
  if (!existsSync(logPath)) {
    writeText(logPath, `# Log\n\n${line}`)
    return
  }
  writeFileSync(logPath, `${readFileSync(logPath, 'utf8').trimEnd()}\n\n${line}`)
}

function installWiki(files, agent, pdRoot, brainRoot) {
  let pages = 0
  for (const [rel, raw] of Object.entries(files)) {
    if (!rel.startsWith('wiki/')) continue
    const dest = join(brainRoot, rel)
    writeText(dest, rewritePaths(raw, agent, pdRoot, brainRoot))
    pages++
  }
  ensureIndex(brainRoot)
  appendLog(brainRoot)
  return pages
}

async function prompt(rl, question, fallback) {
  const suffix = fallback ? ` [${fallback}]` : ''
  const answer = await rl.question(`  ${question}${suffix}\n  > `)
  const v = answer.trim()
  return v || fallback
}

async function main() {
  const args = parseArgs(process.argv.slice(2))
  const config = loadAgenticConfig()
  const guessedPd = args.pd ? expandPath(args.pd) : guessPdRoot(config)
  const guessedBrain = args.brain ? expandPath(args.brain) : guessBrainRoot(config)
  const guessedAgent = normalizeAgent(args.agent) || 'cursor'

  output.write('\n  pd overlay installer (skills + Second Brain wiki)\n\n')

  let pdRoot = guessedPd
  let brainRoot = guessedBrain
  let agent = guessedAgent

  const interactive = Boolean(input.isTTY) && !args.yes
  if (interactive) {
    const rl = createInterface({ input, output })
    pdRoot = expandPath(await prompt(rl, 'Where is the pd codebase?', guessedPd))
    const agentRaw = await prompt(
      rl,
      'Install skills for Cursor or Claude? [cursor/claude]',
      guessedAgent,
    )
    agent = normalizeAgent(agentRaw) || die('Choose cursor or claude')
    brainRoot = expandPath(
      await prompt(rl, 'Where is your Second Brain vault?', guessedBrain),
    )
    rl.close()
  } else {
    agent = normalizeAgent(args.agent || process.env.PD_AGENT || guessedAgent)
    if (!agent) die('Set --agent cursor|claude')
    pdRoot = expandPath(args.pd || process.env.PD_ROOT || guessedPd)
    brainRoot = expandPath(args.brain || process.env.PD_BRAIN || guessedBrain)
  }

  if (!pdRoot) die('pd path is required')
  if (!existsSync(pdRoot)) die(`pd path does not exist: ${pdRoot}`)
  // TEMP: skip pd-repo shape check so install can be simulated in an empty folder
  // if (!looksLikePd(pdRoot)) {
  //   warn(`This does not look like the pd monorepo: ${pdRoot}`)
  //   if (interactive) die('Aborting. Pass the folder that contains apps/book_service.')
  // }
  if (!agent) die('Choose cursor or claude')

  const files = filesFromArchive()
  const overlay = installOverlay(files, agent, pdRoot, brainRoot)
  const pages = installWiki(files, agent, pdRoot, brainRoot)

  log(`Agent:      ${agent}`)
  log(`pd:         ${pdRoot}`)
  log(`Vault:      ${brainRoot}`)
  log(`Skills:     ${overlay.skills} files → ${agent === 'claude' ? '.claude/skills' : '.cursor/skills'}`)
  log(`Rules:      ${overlay.rules} files → ${agent === 'claude' ? '.claude/rules' : '.cursor/rules'}`)
  log(`Wiki pages: ${pages} → wiki/projects/pd + wiki/concepts/book-manager.md`)
  log('Done. Restart Cursor / Claude Code so the overlay loads.')
}

main().catch((err) => {
  die(err instanceof Error ? err.message : String(err))
})
